const originalCategoryDetails=categoryDetails;
categoryDetails=index=>{if(!imported){originalCategoryDetails(index);return}const c=categories[index];if(!c)return;const a=analysis();const e=document.createElement('div');e.className='modal';e.innerHTML=`<section class="sheet category-sheet" role="dialog" aria-modal="true" aria-label="${E(c.name)} details"><header class="top"><h2>${E(c.name)}</h2>${button(icon('close'),'close-modal','icon-button','aria-label="Close"')}</header><p class="month">${E(a.periodLabel)}</p><div class="category-detail-amount">${money(c.spent)}</div><p>confirmed spending</p>${configured&&focus.includes(c.name)?`<p>${money(c.limit-c.spent)} left from your ${money(c.limit)} target</p>`:''}<div class="activity-list">${a.expenses.filter(r=>r.category===c.name).map(r=>`<div class="activity-row"><div><b>${E(r.merchant)}</b><small>${shortDate(r.date)}</small></div><strong>${E(fmt(r.cents))}</strong></div>`).join('')}</div>${c.name!=='Rent & bills'?button('Edit goals','category-targets'):''}</section>`;document.body.append(e)};
render=()=>{if(view==='upload'){renderUpload();return}if(view==='review'){renderReview();return}originalRender();if(imported&&view==='limits'){document.querySelectorAll('.limit p').forEach((p,i)=>p.textContent='Confirmed spending '+money(active()[i].spent));document.querySelectorAll('[data-field="target"]').forEach((el,i)=>{el.min=0;el.closest('.limit').querySelector('.range-label span:first-child').textContent=money(0);el.max=Math.max(800,Math.ceil(active()[i].avg*2/100)*100);el.closest('.limit').querySelector('.range-label span:last-child').textContent=money(+el.max)})}if(!imported&&view==='dashboard'&&tab==='wrapped'){const tile=document.querySelector('.recap-tile');if(tile)tile.insertAdjacentHTML('afterend',button('Build from your receipts','go:upload','secondary'))}};
dispatch=action=>{if(action.startsWith('chart-detail:')){paused=true;lastTick=Date.now();renderStory();const a=imported?analysis():demoAnalysis();const c=a.categories[+action.split(':')[1]];if(c)toast(c.name+': '+fmt(c.cents,imported?.currency||'USD'));return}if(action==='review-import'){reviewPage=0;reviewAcknowledged=false;go('review');return}if(action==='manual-import'){manualImport();return}if(action==='review-existing'){appendImport=false;pendingRows=imported.rows.map(r=>({...r}));pendingHashes=imported.hashes||[];pendingReports=[];reviewPage=0;reviewAcknowledged=false;go('review');return}if(action==='review-prev'||action==='review-next'){reviewPage=Math.max(0,Math.min(Math.ceil(pendingRows.length/15)-1,reviewPage+(action==='review-next'?1:-1)));renderReview();window.scrollTo(0,0);return}if(action==='confirm-import'){confirmImport();return}if(action==='export-purchases'){exportPurchases();return}if(action==='reset'){faiitSignOut();return}if(action==='delete-import'){Faiit.ask({title:'Delete your saved data?',body:'This removes your purchases, goals and balances from this device and signs you out.',confirm:'Delete and sign out',danger:true}).then(ok=>{if(ok)faiitWipe()});return}if(action==='go:upload'&&!importBusy){importOptions.currency=imported?.currency||'USD';appendImport=true}if(action==='survey-next'&&imported&&step===1){focus=focus.filter(n=>n!=='Rent & bills')}originalDispatch(action)};
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.reviewIndex!==undefined){const r=pendingRows[+el.dataset.reviewIndex],f=el.dataset.reviewField;if(!r)return;r[f]=f==='cents'?D.amount(el.value):f==='include'?el.checked:el.value;reviewAcknowledged=false;const ack=document.querySelector('[data-review-confirm]');if(ack)ack.checked=false;const saveButton=document.querySelector('[data-action="confirm-import"]');if(saveButton)saveButton.disabled=true}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.field==='real-files'){readUploads([...el.files]);return}if(el.dataset.importOption){importOptions[el.dataset.importOption]=el.value;return}if(el.hasAttribute('data-import-append')){appendImport=el.checked;return}if(el.hasAttribute('data-review-confirm')){reviewAcknowledged=el.checked;document.querySelector('[data-action="confirm-import"]').disabled=!el.checked;return}if(el.dataset.reviewField==='include'){renderReview();return}if(el.hasAttribute('data-period')){imported.period=el.value;syncImported();persistImport();originalSave();renderDashboard()}});

// Money health and habit-led home. Net worth uses explicit balance snapshots.
paths.eye='M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12zM9 12a3 3 0 1 0 6 0 3 3 0 1 0-6 0';
paths.eyeoff='M3 3l18 18M10 5h2c7 0 10 7 10 7s-1 3-4 5M6 6c-3 2-4 6-4 6s3 7 10 7c2 0 3 0 5-1M9 9a4 4 0 0 0 6 6';
let healthSnapshots=[],healthHidden=false,healthPoint=-1;
const balanceFields=[['cash','Cash & checking'],['savings','Savings'],['investments','Investments'],['other','Other assets'],['debts','Debts & loans']];
const todayLocal=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
try{const saved=JSON.parse(localStorage.getItem('mw-health-v1'));if(saved){healthHidden=!!saved.hidden;healthSnapshots=(saved.snapshots||[]).filter(s=>D.date(s.date)&&['USD','GBP','EUR','NGN','CAD'].includes(s.currency)&&balanceFields.every(([k])=>Number.isSafeInteger(s[k])&&s[k]>=0)).slice(-120)}}catch{}
const healthCurrency=()=>imported?.currency||healthSnapshots.at(-1)?.currency||'USD';
const healthTotals=s=>{const assets=s.cash+s.savings+s.investments+s.other;return {...s,assets,net:assets-s.debts}};
function healthData(){const currency=healthCurrency(),saved=healthSnapshots.filter(s=>s.currency===currency).sort((a,b)=>a.date.localeCompare(b.date));if(saved.length)return {demo:false,rows:saved.map(healthTotals),currency};if(imported)return {demo:false,rows:[],currency};const now=new Date();return {demo:true,currency:'USD',rows:[11320,11980,11600,12540].map((n,i)=>{const d=new Date(now);d.setDate(d.getDate()-(3-i)*10);return healthTotals({date:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,currency:'USD',cash:350000,savings:n*100-104000,investments:0,other:0,debts:246000})})}}
function persistHealth(){try{localStorage.setItem('mw-health-v1',JSON.stringify({hidden:healthHidden,snapshots:healthSnapshots}));return true}catch{toast('Could not save balances. Free up browser storage and try again.');return false}}
function healthGraph(data){if(healthHidden)return '<div class="health-chart chart-private"><span>Balances hidden</span></div>';const rows=data.rows;if(rows.length<2)return `<div class="health-chart chart-empty"><span class="snapshot-orbit" aria-hidden="true"></span><p>${rows.length?'Your first snapshot.':'Your money picture starts here.'}<br><span>${rows.length?'The next one starts your trend.':'Add what you own and owe.'}</span></p></div>`;const range=Math.max(...rows.map(r=>r.net))-Math.min(...rows.map(r=>r.net)),min=Math.min(...rows.map(r=>r.net));const visible=rows.slice(-12),points=visible.map((r,i)=>({x:18+i/(visible.length-1)*344,y:range?108-(r.net-min)/range*84:66,r,index:rows.length-visible.length+i}));return `<div class="health-chart"><svg viewBox="0 0 380 148" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="health-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".45"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient></defs><path d="M${points[0].x} 148 ${points.map(p=>'L'+p.x+' '+p.y).join(' ')} L362 148Z" fill="url(#health-fill)"/><path class="health-trend-line" d="${points.map((p,i)=>(i?'L':'M')+p.x+' '+p.y).join(' ')}"/>${points.map(p=>`<path d="M${p.x} ${p.y}V148" class="health-guide"/><circle cx="${p.x}" cy="${p.y}" r="5" class="health-dot"/>`).join('')}</svg>${points.map(p=>button('','health-point:'+p.index,'health-dot-button',`style="left:${p.x/380*100}%;top:${p.y/148*100}%" aria-label="${E(shortDate(p.r.date))}: ${E(fmt(p.r.net,data.currency))}" aria-pressed="${healthPoint===p.index}"`)).join('')}<div class="health-axis"><span>${shortDate(visible[0].date)}</span><span>${shortDate(visible.at(-1).date)}</span></div></div>`}
function healthHero(){const data=healthData(),current=data.rows.at(-1),selected=data.rows[healthPoint]||current;return `<section class="health-hero ${current?'':'health-blank'}" aria-label="Your money health"><div class="health-glow" aria-hidden="true"></div><div class="health-heading"><h1>Your net worth</h1>${button(icon(healthHidden?'eyeoff':'eye'),'toggle-health','health-eye',`aria-label="${healthHidden?'Reveal':'Hide'} balances" aria-pressed="${healthHidden}"`)}</div><div class="health-figure"><strong class="${selected&&String(selected.net).length>9?'health-long':''}">${healthHidden?'••••••':selected?E(fmt(selected.net,data.currency)):'—'}</strong><span class="currency-chip">${E(data.currency)}</span></div><p class="health-caption">${data.demo?'Sample balances':selected?'Assets minus debts':'Add balances to see your net worth'}</p>${healthGraph(data)}${current?`<div class="health-breakdown"><div><span>What you own</span><strong>${healthHidden?'••••':E(fmt(selected.assets,data.currency))}</strong></div><div><span>What you owe</span><strong>${healthHidden?'••••':E(fmt(selected.debts,data.currency))}</strong></div></div><div class="health-update"><span>${healthPoint>=0&&selected!==current?'Snapshot':'Updated'} ${shortDate(selected.date)}</span>${button(data.demo?'Add your balances':'Update balances','edit-health','health-link')}</div>`:button('Add your balances','edit-health','health-add')}</section>`}
function habitArt(name){if(name==='Cafés')return '<img src="assets/wrapped-coffee.png" alt="" class="habit-coffee">';if(name==='DoorDash'||name==='Food delivery'||name==='Dining')return '<span class="habit-takeout"><i></i><b></b></span><span class="habit-fork"></span>';if(name==='Shopping')return '<span class="habit-shopping"><i></i></span><span class="habit-shopping second"><i></i></span>';if(name==='Groceries')return '<span class="habit-orange"></span><span class="habit-leaf"></span><span class="habit-orange second"></span>';return `<span class="habit-token">${icon(D.icons[name]||'wallet')}</span><span class="habit-spark">✳</span>`}
function habitTitle(name){return ({DoorDash:'Your kitchen misses you.','Food delivery':'Your kitchen misses you.',Cafés:'Your daily plot fuel.',Shopping:'Just browsing. Sure.',Groceries:'Chef era loading.',Dining:'A seat at the table.',Transport:'Places to be.',Subscriptions:'Still subscribed.',Travel:'Out of office.',Health:'Looking after you.','Rent & bills':'Keeping life running.',Education:'Brain gains.',Other:'The little extras.'})[name]||'Part of your everyday.'}
function habitCards(){const list=categories.map((c,i)=>({c,i}));return `<div class="habit-cards">${list.map(({c,i})=>{const amount=imported?c.spent:configured?c.spent:c.avg;const track=configured&&focus.includes(c.name),remaining=c.limit-c.spent;return button(`<span class="habit-category">${E(c.name)}${icon('arrow')}</span><span class="habit-art" aria-hidden="true">${habitArt(c.name)}</span><span class="habit-title">${habitTitle(c.name)}</span><span class="habit-money">${money(amount)}</span><span class="habit-caption">spent this month</span>${track?`<span class="habit-focus">${money(Math.abs(remaining))} ${remaining<0?'above your focus':'left in your focus'}</span>`:''}`,'category:'+i,'habit-card habit-tone-'+(i%4))}).join('')}</div>`}
function habitsHome(){const a=imported?analysis():null,total=a?a.total/100:categories.reduce((s,c)=>s+(configured?c.spent:c.avg),0),period=a?a.periodLabel:configured?'October 2026':'September 2026';const monthControl=a?`<label class="habit-period"><span class="sr-only">Spending month</span><select data-period>${a.periods.map(p=>`<option value="${p}" ${p===a.period?'selected':''}>${new Intl.DateTimeFormat('en-US',{month:'short',year:'numeric'}).format(new Date(p+'-02T12:00:00'))}</option>`).join('')}</select></label>`:`<span class="habit-period">${period}</span>`;app.innerHTML=`<section class="screen dashboard habits-home"><header class="health-top"><div class="health-brand">${mark()}<span>Faiit</span></div>${button(icon('upload'),'go:upload','frost-icon','aria-label="Add receipts or statements"')}</header>${healthHero()}<div class="habits-heading"><h2>Money habits</h2>${monthControl}</div><p class="habits-intro"><strong>${money(total)}</strong> spent ${a?'in your uploaded records':'in sample activity'}.</p><div class="wrapped-invitation"><div><span>Your month has a story.</span><h2>Let’s unwrap it.</h2>${button(`Watch your Wrapped ${icon('arrow')}`,'start-story','wrapped-invitation-link')}</div><span class="wrapped-orb" aria-hidden="true"><i></i><i></i><i></i></span></div>${categories.length?habitCards():'<div class="habit-empty"><h2>No purchases here yet.</h2><p>Add receipts or choose another month to find your patterns.</p></div>'}<div class="focus-invitation"><div>${icon('target')}<h2>One thing at a time.</h2></div><p>Choose a habit you want to change. You set the pace.</p>${button(configured?'Adjust your focus':'Choose your focus',configured?'go:limits':'edit-goals','secondary',categories.some(c=>c.name!=='Rent & bills')?'':'disabled')}</div><div class="habit-tools">${button(`${icon('upload')}Add receipts or statements`,'go:upload','journal-tool')}${imported?button(`${icon('edit')}Review your purchases`,'review-existing','journal-tool'):''}</div></section>${footer()}`}
const priorDashboard=renderDashboard;
renderDashboard=()=>{if(tab==='home')habitsHome();else{priorDashboard();if(tab==='you'){const el=document.querySelector('.profile-rows');el?.insertAdjacentHTML('afterend',button('Manage your balances','edit-health','secondary'));document.querySelector('.dashboard')?.insertAdjacentHTML('beforeend',button('Sign out','faiit-signout','secondary'))}}};
function editHealth(){const data=healthData(),current=data.demo?null:data.rows.at(-1);document.querySelector('.modal')?.remove();const el=document.createElement('div');el.className='modal';el.innerHTML=`<section class="sheet balance-sheet" role="dialog" aria-modal="true" aria-labelledby="balance-title"><header class="top"><h2 id="balance-title">Your money picture</h2>${button(icon('close'),'close-modal','icon-button','aria-label="Close balances"')}</header><p>What you own, minus what you owe. Use current balances; enter 0 where it doesn’t apply.</p><form id="balance-form"><label>Currency<select name="currency" ${imported?'disabled':''}>${['USD','GBP','EUR','NGN','CAD'].map(c=>`<option ${c===data.currency?'selected':''}>${c}</option>`).join('')}</select></label>${balanceFields.map(([k,label])=>`<label>${label}<input name="${k}" type="number" inputmode="decimal" min="0" max="1000000000000" step="0.01" value="${current?(current[k]/100).toFixed(2):''}" placeholder="0.00" required></label>`).join('')}<p class="balance-error" id="balance-error" role="alert"></p><button class="primary" type="submit">Save today’s balances</button><p class="balance-storage">Saved on this device. No account numbers needed.</p>${current?button('Delete balance history','delete-health','text-button','type="button"'):''}</form></section>`;document.body.append(el);el.querySelector('input').focus()}
function saveBalances(form){const currency=imported?.currency||form.elements.currency.value;const values=Object.fromEntries(balanceFields.map(([k])=>[k,D.amount(form.elements[k].value)]));if(!Object.values(values).every(n=>Number.isSafeInteger(n)&&n>=0&&n<=1e14)){document.getElementById('balance-error').textContent='Enter a valid amount for each balance. Use 0 where needed.';return}const snapshot={date:todayLocal(),currency,...values};const previous=healthSnapshots;healthSnapshots=[...healthSnapshots.filter(s=>!(s.date===snapshot.date&&s.currency===currency)),snapshot].slice(-120);if(!persistHealth()){healthSnapshots=previous;return}healthPoint=-1;document.querySelector('.modal')?.remove();renderDashboard();toast('Your money picture is updated.')}
const priorHealthDispatch=dispatch;
dispatch=action=>{if(action==='faiit-signout'){faiitSignOut();return}if(action==='toggle-health'){healthHidden=!healthHidden;persistHealth();habitsHome();document.querySelector('[data-action="toggle-health"]')?.focus();return}if(action==='edit-health'){editHealth();return}if(action.startsWith('health-point:')){healthPoint=+action.split(':')[1];habitsHome();document.querySelector(`[data-action="${action}"]`)?.focus();return}if(action==='delete-health'){Faiit.ask({title:'Delete your balance history?',body:'All balance snapshots saved on this device will be removed.',confirm:'Delete',danger:true}).then(ok=>{if(ok){healthSnapshots=[];healthPoint=-1;persistHealth();document.querySelector('.modal')?.remove();renderDashboard()}});return}priorHealthDispatch(action)};
document.addEventListener('submit',e=>{if(e.target.id==='balance-form'){e.preventDefault();saveBalances(e.target)}});
document.addEventListener('change',e=>{if(e.target.closest('#balance-form')&&e.target.name==='currency'){const form=e.target.form;const entry=healthSnapshots.filter(s=>s.currency===e.target.value).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);balanceFields.forEach(([k])=>form.elements[k].value=entry?(entry[k]/100).toFixed(2):'')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.balance-sheet'))document.querySelector('.modal')?.remove()});

// Faiit: welcome + phone sign up / sign in, money source picker, hello screen, then Wrapped.
const faiitPrevRender=render;
// Sign out clears everything this prototype keeps on the device, then returns to the welcome screen.
const faiitWipe=()=>{['faiit-user-v1','mw-v3','mw-import-v1','mw-health-v1'].forEach(k=>{try{localStorage.removeItem(k)}catch{}});
 // Reset in-memory state as well, so signing out works even if the frame blocks a reload.
 imported=null;configured=false;transactions=[];customStories=[];pendingRows=[];pendingReports=[];healthSnapshots=[];healthPoint=-1;goal='Spend less';focus=['DoorDash','Shopping','Cafés'];tab='home';step=0;
 categories.splice(0,categories.length,{name:'DoorDash',icon:'cart',avg:650,limit:300,spent:0},{name:'Shopping',icon:'bag',avg:420,limit:200,spent:0},{name:'Cafés',icon:'coffee',avg:180,limit:100,spent:0},{name:'Groceries',icon:'groceries',avg:360,limit:320,spent:0});
 money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:n%1?2:0,maximumFractionDigits:2}).format(n);slides=sampleSlides.slice();
 FaiitHome.reset();document.querySelector('.fh-sheet-wrap')?.remove();
 document.querySelector('.modal')?.remove();history.replaceState({view:'welcome'},'',location.pathname+location.search);go('welcome',false)};
const faiitSignOut=()=>Faiit.ask({title:'Sign out of Faiit?',body:'Your purchases, goals and balances on this device will be cleared.',confirm:'Sign out',danger:true}).then(ok=>{if(ok)faiitWipe()});
// Order: connect a bank or upload → hello + Unwrap → decoding → Wrapped.
const faiitSourced=()=>!!(configured||imported||Faiit.user()?.sourced);
const faiitHome=()=>!faiitSourced()?'connect':Faiit.needsHello()?'hello':'dashboard';
const faiitToHello=()=>{Faiit.patch({sourced:true});history.replaceState({view:'hello',tab,step},'',location.pathname);go('hello',false)};
// Upload straight from the file picker: read on this device, keep the valid purchases, then go to decoding.
async function faiitImportFiles(files,onProgress){
 let reader;try{reader=await import('./import-reader.mjs?v=16')}catch{return {error:'The file reader didn’t load. Check your connection and try again.'}}
 const rows=[];let lastErr='';const opts={...importOptions};
 for(let i=0;i<files.length;i++){const f=files[i];
  const label=/\.(png|jpe?g|webp)$/i.test(f.name)?'Reading your photo':/\.csv$/i.test(f.name)?'Reading your CSV':'Reading your statement';
  const step=m=>{let x=.2;const pg=/page (\d+) of (\d+)/i.exec(m||''),pc=/(\d+)%/.exec(m||'');if(pg)x=(+pg[1]-.4)/+pg[2];else if(pc)x=.15+.8*(+pc[1]/100);onProgress((i+Math.min(.95,x))/files.length,label)};
  try{onProgress((i+.08)/files.length,'Uploading');const res=await reader.readFile(f,{...opts,source:f.name},step);rows.push(...res.rows)}
  catch(e){const m=e.message||'';lastErr=/15 MB|larger than/i.test(m)?'That file is over 15 MB. Try a smaller one.':/HEIC|Choose CSV/i.test(m)?'That file type isn’t supported. Use a PDF, CSV or photo (JPG, PNG).':/20 pages/i.test(m)?'That statement is over 20 pages. Try one month at a time.':''}}
 const good=rows.filter(r=>r.include!==false&&!D.issues(r).length);
 if(!good.length)return {error:lastErr||'We couldn’t find purchases in that file. Try a CSV export from your bank.'};
 const counts={};good.forEach(r=>counts[r.currency]=(counts[r.currency]||0)+1);const cur=Object.keys(counts).sort((a,b)=>counts[b]-counts[a])[0];
 imported={rows:good.filter(r=>r.currency===cur).map(({note,include,...r})=>({...r,include:true})),currency:cur,hashes:[],period:''};
 configured=false;focus=[];categories.splice(0);syncImported();persistImport();originalSave();
 const n=analysis().count;
 if(!n){imported=null;try{localStorage.removeItem('mw-import-v1')}catch{}return {error:'We found money in and transfers, but no purchases.'}}
 onProgress(1,'Done');return {count:n};
}
// A real Plaid connection (when configured) still goes through review.
window.FaiitApp={importRows(rows,source='Bank connection'){appendImport=!!imported;pendingRows=rows;pendingHashes=[];pendingReports=[{name:source,message:rows.length+' transactions found; review required.'}];reviewPage=0;reviewAcknowledged=false;go('review')},toast};
// Dashboard data: this month's spending by category, from the import or the demo sample.
const faiitSample={periodLabel:'September 2026',currency:'USD',total:161000,categories:[{name:'Food delivery',cents:65000,count:28},{name:'Shopping',cents:42000,count:9},{name:'Groceries',cents:36000,count:11},{name:'Cafés',cents:18000,count:22}]};
const faiitSpend=()=>{if(!imported)return faiitSample;const a=analysis();return {periodLabel:a.periodLabel,currency:imported.currency,total:a.total,categories:a.categories.map(c=>({name:c.name,cents:c.cents,count:c.count}))}};
// Spending by category for one calendar month (YYYY-MM), from imported rows only.
const faiitSpendIn=key=>{const out={};if(!imported)return out;for(const r of imported.rows){if(r.kind==='expense'&&r.date?.startsWith(key))out[r.category]=(out[r.category]||0)+r.cents}return out};
// Months with purchases (YYYY-MM), and daily spending in one month, for the recap card.
const faiitMonths=()=>{if(!imported)return [];const set=new Set();for(const r of imported.rows)if(r.kind==='expense'&&r.date)set.add(r.date.slice(0,7));return [...set].sort()};
const faiitDaily=key=>{const days=new Array(31).fill(0);if(!imported)return days;for(const r of imported.rows){if(r.kind==='expense'&&r.date?.startsWith(key)){const d=+r.date.slice(8,10);if(d>=1&&d<=31)days[d-1]+=r.cents}}return days};
const faiitApi=()=>({spend:faiitSpend,spendIn:faiitSpendIn,months:faiitMonths,daily:faiitDaily,hasData:()=>!!imported,money:c=>fmt(Math.round(c),imported?.currency||'USD'),toast,user:()=>Faiit.user(),
 phone:()=>{const u=Faiit.user();return u?`${({US:'+1',CA:'+1',NG:'+234',GB:'+44',GH:'+233',KE:'+254',RW:'+250',ZA:'+27',IN:'+91',ES:'+34'})[u.iso]||''} ${Faiit.formatPhone(u.iso,u.phone)}`:''},
 setName:n=>Faiit.setName(n),setTab:t=>{tab=t},openRecap:(k,from)=>{faiitReturnTab=from||'home';startStory(k)},openBreakdown:(k,from)=>{faiitReturnTab=from||'home';faiitBreakKey=k||null;go('breakdown')},wrapRows:()=>imported?.rows||FaiitRecap.sampleRows(),isSample:()=>!imported,addStatement:()=>{importOptions.currency=imported?.currency||'USD';appendImport=true;go('upload')},
 review:()=>{if(!imported){toast('Add a statement first to review purchases.');return}dispatch('review-existing')},signout:faiitSignOut,
 done:()=>{configured=true;save();tab='home';history.replaceState({view:'dashboard',tab,step},'',location.pathname);go('dashboard',false)}});
// The recap is an interactive episode (faiit-wrap.js), built from the latest month of purchases or the sample month.
let faiitWrapMonth=null,faiitBreakKey=null,faiitReturnTab='home';
startStory=(key)=>{
 if(typeof key!=='string')key=null;
 if(imported){const a=key?D.analyze(imported.rows,key):analysis();if(!a.count){tab='home';go('dashboard');toast('Add a confirmed spending entry to build your Wrapped.');return}faiitWrapMonth={key:a.period,label:a.periodLabel,rows:a.rows,sample:false}}else faiitWrapMonth=key?FaiitWrap.sampleMonth(key):null;
 returnFromStory=configured||(imported&&!categories.some(c=>c.name!=='Rent & bills'));go('wrap')};
render=function(){
 app.onclick=null;app.oninput=null;
 if(view==='breakdown'){Faiit.leave();FaiitRecap.render(app,{rows:imported?.rows||null,key:faiitBreakKey,openWrap:()=>startStory(),money:c=>fmt(Math.round(c),imported?.currency||'USD'),toast,back:()=>{tab=faiitReturnTab||'home';faiitReturnTab='home';history.replaceState({view:'dashboard',tab,step},'',location.pathname);go('dashboard',false)}});return}
 if(view==='wrap'){Faiit.leave();FaiitWrap.play(app,{month:faiitWrapMonth,money:c=>fmt(Math.round(c),imported?.currency||'USD'),toast,onExit:()=>{if(returnFromStory||!FaiitHome.needsPlan()){tab=faiitReturnTab||'home';faiitReturnTab='home';history.replaceState({view:'dashboard',tab,step},'',location.pathname);go('dashboard',false)}else{step=0;history.replaceState({view:'survey',tab,step},'',location.pathname);go('survey',false)}}});return}
 if(view==='survey'||view==='limits'||view==='plan'){if(!FaiitHome.needsPlan()){view='dashboard'}else{Faiit.leave();FaiitHome.plan(app,faiitApi());return}}
 if(view==='dashboard'){Faiit.leave();if(FaiitHome.needsPlan()){FaiitHome.plan(app,faiitApi());return}if(!['home','wraps','cards','profile'].includes(tab))tab='home';FaiitHome.home(app,faiitApi(),tab);return}
 if(view==='welcome'){if(Faiit.user()){go(faiitHome(),false);return}Faiit.render(app,{done:()=>{history.replaceState({view:faiitHome(),tab,step},'',location.pathname);go(faiitHome(),false)}});return}
 if(view==='hello'){if(!faiitSourced()){go('connect',false);return}Faiit.hello(app,{go:()=>{history.replaceState({view:'decoding',tab,step},'',location.pathname);go('decoding',false)}});return}
 if(view==='connect'){Faiit.source(app,{bank:()=>{if(window.FaiitPlaid?.ready())FaiitPlaid.open();else go('fbank')},importFiles:faiitImportFiles,done:faiitToHello,signout:faiitSignOut});return}
 if(view==='fbank'){Faiit.bank(app,{connected:(name,accts)=>{bank=name;selectedAccounts=accts;faiitToHello()}});return}
 if(view==='decoding'){Faiit.decoding(app,{done:()=>{history.replaceState({view:faiitHome(),tab,step},'',location.pathname);startStory()}});return}
 Faiit.leave();if(view==='splash'){app.innerHTML=Faiit.splash();return}return faiitPrevRender.apply(this,arguments)};
if(!Faiit.user()){view='welcome';history.replaceState({view:'welcome'},'',location.pathname);render()}
else{history.replaceState({view:'connect',tab,step},'',location.pathname);render();splashTimer=setTimeout(()=>go(faiitHome(),false),1300)}
